    ldr x0, [x1, Lrt_owned@PAGEOFF]
    ldr x2, [x0, #8]
    str x2, [x1, Lrt_owned@PAGEOFF]
    ldr x0, [x0]
    b _bit_drop_str

_bit_setjmp:                        // x0 = буфер → 0; сохраняет x19-x30, sp, d8-d15
