    ldp x21, x22, [x0, #16]
    ldp x23, x24, [x0, #32]
    ldp x25, x26, [x0, #48]
    ldp x27, x28, [x0, #64]
    ldp x29, x30, [x0, #80]
    ldr x2, [x0, #96]
    mov sp, x2
    ldp d8, d9, [x0, #104]
    ldp d10, d11, [x0, #120]
    ldp d12, d13, [x0, #136]
    ldp d14, d15, [x0, #152]
    mov x0, x1
    ret

_bit_term_errcode:                  // → код последней пойманной ошибки (0 = без кода)
    adrp x1, Lrt_errcode@PAGE
    ldr x0, [x1, Lrt_errcode@PAGEOFF]
    ret

_bit_errno_map:                     // w0 = код ошибки системы → 1 отказ, 2 таймаут, 3 нет маршрута, 0 без кода
