    b.eq 1f
    cmp w0, #60                        // ETIMEDOUT (Darwin)
    b.eq 2f
    cmp w0, #51                        // ENETUNREACH (Darwin)
    b.eq 3f
    cmp w0, #65                        // EHOSTUNREACH (Darwin)
    b.eq 3f
    mov w0, #0
    ret
